import json, math

def verify(answer):
    """Mechanical GRPO verifier for batch-004 scenario 1 (The Clamped Corridor on the Rookie Prop).
    Recomputes the CQR rank index, clamped coverage, defect, minimum calibration size,
    Ville wealth threshold and wealth product; checks the refractory, conjunctive-gate,
    and dose-feasibility vetoes and the fail-closed decision."""
    if isinstance(answer, str):
        try:
            answer = json.loads(answer)
        except Exception:
            return False
    if not isinstance(answer, dict):
        return False
    expected = {
        "cqr_rank_index_k", "clamp_admissible", "true_coverage_if_clamped",
        "advertised_coverage", "coverage_defect_probability_points",
        "min_calibration_n_for_90pct", "required_output_at_n5",
        "ville_alpha_threshold", "ville_wealth_threshold", "wealth_after_three_games",
        "execution_unlocked", "static_p_peeking_valid",
        "counterfactual_reversal_time_ms", "counterfactual_reversal_admissible",
        "refractory_window_ms", "postural_gate_fires", "conjunctive_and_required",
        "static_dose_admissible_after_fatigue_flare", "deployment_decision",
    }
    if set(answer.keys()) != expected:
        return False
    def num(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool)
    # (1) CQR counting argument [409f5dad119c06ed:p1, p.35; p2, p.37]
    n, alpha = 5, 0.10
    k = math.ceil((n + 1) * (1 - alpha))  # ceil(5.4) = 6
    if answer.get("cqr_rank_index_k") != k:
        return False
    if answer.get("clamp_admissible") is not False:
        return False
    cov = n / (n + 1)  # 5/6
    tc = answer.get("true_coverage_if_clamped")
    if not num(tc) or not math.isclose(tc, cov, rel_tol=1e-6, abs_tol=1e-9):
        return False
    ac = answer.get("advertised_coverage")
    if not num(ac) or not math.isclose(ac, 0.90, rel_tol=0.0, abs_tol=1e-9):
        return False
    defect = (0.90 - cov) * 100.0  # 6.6667 probability points
    cd = answer.get("coverage_defect_probability_points")
    if not num(cd) or not math.isclose(cd, defect, rel_tol=1e-6, abs_tol=1e-4):
        return False
    n_min = math.ceil(1 / alpha) - 1  # 9
    if answer.get("min_calibration_n_for_90pct") != n_min:
        return False
    if answer.get("required_output_at_n5") != "abstain_or_unbounded":
        return False
    # (2) Ville anytime gate [409f5dad119c06ed:p8, pp.46-47]
    at = answer.get("ville_alpha_threshold")
    if not num(at) or not math.isclose(at, 0.05, rel_tol=0.0, abs_tol=1e-12):
        return False
    wt = answer.get("ville_wealth_threshold")
    if not num(wt) or not math.isclose(wt, 1 / 0.05, rel_tol=1e-9, abs_tol=1e-9):
        return False
    wealth = 1.2 * 1.5 * 0.8  # 1.44
    w = answer.get("wealth_after_three_games")
    if not num(w) or not math.isclose(w, wealth, rel_tol=1e-9, abs_tol=1e-9):
        return False
    if answer.get("execution_unlocked") is not False:
        return False
    if answer.get("static_p_peeking_valid") is not False:
        return False
    # (3) Hip-flip refractory [409f5dad119c06ed:p5, p.19]
    rt = answer.get("counterfactual_reversal_time_ms")
    if not num(rt) or not math.isclose(rt, 150, rel_tol=0.0, abs_tol=1e-9):
        return False
    if answer.get("counterfactual_reversal_admissible") is not False:
        return False
    rw = answer.get("refractory_window_ms")
    if not isinstance(rw, list) or len(rw) != 2 or rw != [200, 400]:
        return False
    if not (150 < rw[0]):  # reversal at 150 ms precedes the minimum refractory duration -> phantom
        return False
    # (4) Conjunctive protective gate [47da7cd12f78ad9c:p1, p.49]
    if answer.get("postural_gate_fires") is not False:
        return False
    if answer.get("conjunctive_and_required") is not True:
        return False
    # (5) Dose feasibility [47da7cd12f78ad9c:p2, p.46]
    if answer.get("static_dose_admissible_after_fatigue_flare") is not False:
        return False
    # Fail-closed decision
    if answer.get("deployment_decision") != "veto_fail_closed":
        return False
    return True

import json, math

def verify(answer):
    """Mechanical GRPO verifier for batch-004 scenario 2 (The Mean-Field Dynasty).
    Recomputes the mean-field susceptibility/vertex, the ladder-renormalized coupling
    and control, and the random playoff precision; checks the transition-shape,
    scale-separation, regime-break, autocorrelation, plural-recipe, and staff-composition
    vetoes and the fail-closed decision."""
    if isinstance(answer, str):
        try:
            answer = json.loads(answer)
        except Exception:
            return False
    if not isinstance(answer, dict):
        return False
    expected = {
        "mean_field_control_nuU", "chi_mean_field", "vertex_mean_field",
        "renormalized_U_tilde", "renormalized_control_nuUtilde",
        "instability_within_controlled_regime", "mean_field_overestimates_ordering",
        "transition_order", "gradual_ramp_warning_admissible", "precursor_monitoring_licensed",
        "log_claim_licensed_without_scale_separation", "random_baseline_precision",
        "model_beats_persistence", "pool_pre_post_1994_admissible", "iid_ratings_admissible",
        "single_metric_coach_grading_admissible", "assistant_experience_share",
        "assistant_threshold_met", "first_year_penalty_feature", "dynasty_decision",
    }
    if set(answer.keys()) != expected:
        return False
    def num(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool)
    # (1) Mean-field arithmetic [3c1295822da31ba0:p2, p.3]
    nu, U = 0.5, 1.5
    nuU = nu * U  # 0.75
    chi = 2 * nu / (1 - nuU)  # 4
    gamma = 1 / (1 - nuU)  # 4
    for key, val in (("mean_field_control_nuU", nuU), ("chi_mean_field", chi), ("vertex_mean_field", gamma)):
        x = answer.get(key)
        if not num(x) or not math.isclose(x, val, rel_tol=1e-9, abs_tol=1e-9):
            return False
    # (2) Ladder renormalization [3c1295822da31ba0:p4, p.6]
    U_t = U / (1 + 0.5 * nuU * math.log(20))
    nuU_t = nu * U_t
    ut = answer.get("renormalized_U_tilde")
    if not num(ut) or not math.isclose(ut, U_t, rel_tol=1e-6, abs_tol=1e-9):
        return False
    nut = answer.get("renormalized_control_nuUtilde")
    if not num(nut) or not math.isclose(nut, nuU_t, rel_tol=1e-6, abs_tol=1e-9):
        return False
    if answer.get("instability_within_controlled_regime") is not (nuU_t >= 1):
        return False
    if answer.get("mean_field_overestimates_ordering") is not True:
        return False
    # (3) Transition shape [3c1295822da31ba0:p1, p.1; p3, p.3]
    if answer.get("transition_order") != "first_order_with_diverging_precursor":
        return False
    if answer.get("gradual_ramp_warning_admissible") is not False:
        return False
    if answer.get("precursor_monitoring_licensed") is not True:
        return False
    # (4) Scale separation [3c1295822da31ba0:p5, p.4]
    if answer.get("log_claim_licensed_without_scale_separation") is not False:
        return False
    # (5) Playoff precision and regime break [719c464f186464cd:p4, p.6; p6, p.6]
    rb = answer.get("random_baseline_precision")
    if not num(rb) or not math.isclose(rb, 14 / 32, rel_tol=1e-9, abs_tol=1e-9):
        return False
    if answer.get("model_beats_persistence") is not (0.63 > 0.57):
        return False
    if answer.get("pool_pre_post_1994_admissible") is not False:
        return False
    # (6) Relational vetoes [719c464f186464cd:p7, p.7; p3, p.5]
    if answer.get("iid_ratings_admissible") is not False:
        return False
    if answer.get("single_metric_coach_grading_admissible") is not False:
        return False
    # (7) Staff composition [719c464f186464cd:p5, p.5]
    ae = answer.get("assistant_experience_share")
    if not num(ae) or not math.isclose(ae, 0.30, rel_tol=0.0, abs_tol=1e-9):
        return False
    if answer.get("assistant_threshold_met") is not (0.30 >= 0.34):
        return False
    if answer.get("first_year_penalty_feature") != "HeadCoach.year_with_team<=1":
        return False
    # Fail-closed decision
    if answer.get("dynasty_decision") != "veto_mean_field_and_pooling":
        return False
    return True

