    turnover swings, the era RATE gauge, and the regression shadow; checks the rendering,
    job-order, metric-admissibility, objective-reversal, and flat-charge vetoes and the
    fail-closed decision."""
    if isinstance(answer, str):
        try:
            answer = json.loads(answer)
        except Exception:
            return False
    if not isinstance(answer, dict):
        return False
    expected = {
        "loss_post_rate", "settlement_publication_ratio_R", "witness_complete",
        "render_score_as_probability_admissible", "claimed_band_probability",
        "realized_band_probability", "calibration_z", "job_order_correct",
        "metric_admissible_followers", "ep_go_value", "ep_optimal_action",
        "wp_optimal_action", "objective_reversal_present", "flat_turnover_swing",
        "fumble_swing_at_own_30", "flat_charge_admissible", "rate_passer_a",
        "rate_passer_b", "era_gauge_required", "regression_turnover_shadow_per_pair",
        "ledger_decision",
    }
    if set(answer.keys()) != expected:
        return False
    def num(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool)
    def close(key, val, rel=1e-6, abs_=1e-9):
        x = answer.get(key)
        return num(x) and math.isclose(x, val, rel_tol=rel, abs_tol=abs_)
    # (1) Ledger completeness [2626db0663ce780e:xs-witness-loss-completeness, p.2]
    if not close("loss_post_rate", 34 / 46):
        return False
    if not close("settlement_publication_ratio_R", 108 / 150):
        return False
    if answer.get("witness_complete") is not False:
        return False
    # (2) Type discipline [2626db0663ce780e:xs-score-not-probability, p.3]
    if answer.get("render_score_as_probability_admissible") is not False:
        return False
    if not close("claimed_band_probability", 0.8663, rel=0.0, abs_=1e-9):
        return False
    if not close("realized_band_probability", 0.5191, rel=0.0, abs_=1e-9):
        return False
    if not close("calibration_z", -10.7, rel=0.0, abs_=1e-9):
        return False
    # (3) Governance [2626db0663ce780e:xs-lexicographic-job-order, p.1; xs-metric-admissibility, p.8]
    if answer.get("job_order_correct") != "witness>distribution>community>research":
        return False
    if answer.get("metric_admissible_followers") is not False:
