        return False
    if answer.get("ep_optimal_action") != ("go" if ep_go > 1.2 else "punt"):
        return False
    if answer.get("wp_optimal_action") != ("punt" if 0.42 > 0.31 else "go"):
        return False
    if answer.get("objective_reversal_present") is not True:
        return False
    # (5) Turnover conservation and the fumble charge [6cf36a29e51c0a02:hg-turnover-swing, p.108]
