    # (7) Regression shadow [6cf36a29e51c0a02:hg-scoring-regression, p.239]
    if not close("regression_turnover_shadow_per_pair", 2 * 2.08):
        return False
    # Fail-closed decision
    if answer.get("ledger_decision") != "veto_and_rebuild":
        return False
    return True
